package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var schedRecords []SchedRec
var schedIdx int = 0
var curRec SchedRec

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		if len(s) > n {
			return s[:n]
		}
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseDecimalDigits(field string, scale int32) decimal.Decimal {
	f := strings.TrimSpace(field)
	if f == "" {
		return decimal.NewFromInt(0)
	}
	// field contains only digits, possibly with spaces; remove spaces
	f = strings.TrimSpace(f)
	if f == "" {
		return decimal.NewFromInt(0)
	}
	// It should be digits only; parse as integer
	// Allow leading zeros
	// Use decimal.NewFromString then shift?
	// Simpler: parse int64
	// But value may be large; use decimal
	// Remove any non-digit
	clean := ""
	for _, ch := range f {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		return decimal.NewFromInt(0)
	}
	d, err := decimal.NewFromString(clean)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	return d.Shift(-scale)
}

func parseIntField(field string) int64 {
	f := strings.TrimSpace(field)
	if f == "" {
		return 0
	}
	var v int64
	fmt.Sscan(f, &v)
	return v
}

func loadSchedFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if no file, treat as empty
		schedRecords = []SchedRec{}
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// scanner strips \n and \r; need to handle \r already stripped
		// Pad to 16
		if len(line) < 16 {
			line = line + strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		rec := SchedRec{}
		rec.ScAcct = line[0:4]
		rec.ScPrin = parseDecimalDigits(line[4:11], 2)
		rec.ScRate = parseDecimalDigits(line[11:15], 2)
		rec.ScYears = parseIntField(line[15:16])
		schedRecords = append(schedRecords, rec)
	}
}

func pow10Decimal(n int32) decimal.Decimal {
	return decimal.NewFromInt(1).Shift(n)
}

func fitToPicture(v decimal.Decimal, intDigits int32, scale int32) decimal.Decimal {
	total := intDigits + scale
	mod := pow10Decimal(total)
	scaled := v.Shift(scale).Truncate(0)
	// modulo keeping sign
	// for positive, simple Mod
	// Mod in shopspring: signed remainder
	rem := scaled.Mod(mod)
	return rem.Shift(-scale)
}

func formatWsBalEd(v decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99  len 13
	// intDigits=8 frac=2
	intDigits := 8
	// Ensure overflow truncation has already been applied; but if not, apply now for display truncation?
	// High-order digits dropped: keep low-order digits that fit
	// Do fit again to be safe (idempotent)
	fitted := fitToPicture(v, int32(intDigits), 2)
	// Use absolute for formatting (positive)
	abs := fitted.Abs()
	// Get integer and fraction strings with exactly 2 decimals
	s := abs.StringFixed(2) // e.g., "1234.56"
	parts := strings.SplitN(s, ".", 2)
	intStr := parts[0]
	fracStr := "00"
	if len(parts) == 2 {
		fracStr = parts[1]
		if len(fracStr) < 2 {
			fracStr = fracStr + strings.Repeat("0", 2-len(fracStr))
		} else if len(fracStr) > 2 {
			fracStr = fracStr[:2]
		}
	}
	// Truncate high-order digits if longer than intDigits
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	// Pad leading zeros to intDigits
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	digits := []byte(intStr) // length 8
	// digit slot types: 0..6 Z, 7 is 9
	// Determine suppressed display for each digit position
	dispDigits := make([]byte, intDigits)
	suppressing := true
	for i := 0; i < intDigits; i++ {
		isNine := (i == intDigits-1)
		ch := digits[i]
		if isNine {
			dispDigits[i] = ch
			suppressing = false
		} else {
			if suppressing && ch == '0' {
				// check if any non-zero to the right in integer part before the 9? Actually suppression continues until first non-zero
				// Look ahead: if all remaining digits (including 9? but 9 always prints) are zero, we still suppress this Z zero.
				// So condition is simply suppressing && ch=='0'
				dispDigits[i] = ' '
			} else {
				dispDigits[i] = ch
				suppressing = false
			}
		}
	}
	// For suppression detection for commas, we need to know if all digits left of comma are spaces (suppressed)
	// comma1 between d1 and d2 (between intDigits index 1 and 2)
	// comma2 between d4 and d5 (between index 4 and 5) based on 2,3,3 grouping? Let's map:
	// Positions: d0 d1 , d2 d3 d4 , d5 d6 d7(9)
	// commaA after d1 (index1)
	// commaB after d4 (index4)
	commaA := byte(',')
	commaB := byte(',')
	// if all digits 0..1 are spaces (suppressed), commaA becomes space
	allSpace := true
	for i := 0; i <= 1; i++ {
		if dispDigits[i] != ' ' {
			allSpace = false
			break
		}
	}
	if allSpace {
		commaA = ' '
	}
	allSpace = true
	for i := 0; i <= 4; i++ {
		if dispDigits[i] != ' ' {
			allSpace = false
			break
		}
	}
	if allSpace {
		commaB = ' '
	}
	// Build output 13 chars
	out := make([]byte, 13)
	// pic0 -> d0
	out[0] = dispDigits[0]
	out[1] = dispDigits[1]
	out[2] = commaA
	out[3] = dispDigits[2]
	out[4] = dispDigits[3]
	out[5] = dispDigits[4]
	out[6] = commaB
	out[7] = dispDigits[5]
	out[8] = dispDigits[6]
	out[9] = dispDigits[7]
	out[10] = '.'
	out[11] = fracStr[0]
	out[12] = fracStr[1]
	return string(out)
}

func READPARA() {
	if schedIdx >= len(schedRecords) {
		WsEofFlag = "Y"
		return
	}
	curRec = schedRecords[schedIdx]
	schedIdx++
}

func PROCESSPARA() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = fitToPicture(curRec.ScPrin, 8, 2)

	for WsYear = 1; WsYear <= curRec.ScYears; WsYear++ {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE /100)
		rateDiv := curRec.ScRate.Shift(-2)
		one := decimal.NewFromInt(1)
		factor := one.Add(rateDiv)
		prod := WsBal.Mul(factor)
		rounded := prod.Round(2)
		WsBal = fitToPicture(rounded, 8, 2)
		WsBalEd = formatWsBalEd(WsBal)
		yearStr := fmt.Sprintf("%02d", WsYear)
		fmt.Printf("%s Y%s %s\n", curRec.ScAcct, yearStr, WsBalEd)
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", curRec.ScAcct, WsBalEd)
	WsCount++
	READPARA()
}

func MAINPARA() {
	loadSchedFile()
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	countStr := fmt.Sprintf("%02d", WsCount)
	fmt.Printf("SCHEDULES: %s\n", countStr)
}

func main() {
	MAINPARA()
}
